function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function percentToText(value) {
  const numberValue = getNumber(value);
  if (numberValue === null) return "Yok";
  if (numberValue <= 1) return `${Math.round(numberValue * 10000) / 100}%`;
  return `${Math.round(numberValue * 100) / 100}%`;
}

function getWeekKey() {
  const now = new Date();
  const day = now.getDay();
  const diffToMonday = day === 0 ? -6 : 1 - day;

  const monday = new Date(now);
  monday.setDate(now.getDate() + diffToMonday);

  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);

  return `${monday.toISOString().slice(0, 10)}_${sunday.toISOString().slice(0, 10)}`;
}

function findUser(users, userId) {
  return users.find((user) => user.id === userId);
}

function findClass(classes, classId) {
  return classes.find((item) => item.id === classId);
}

function decideSignalType(summary, prediction) {
  const trend = normalize(summary?.fields?.Not_Trendi);
  const absence = getNumber(summary?.fields?.Devamsizlik_Orani);
  const missingAssignments = getNumber(summary?.fields?.Eksik_Odev_Sayisi);
  const lateAssignments = getNumber(summary?.fields?.Gec_Teslim_Sayisi);
  const risk = normalize(summary?.fields?.Risk_Seviyesi || prediction?.fields?.Risk_Seviyesi);

  if (trend === "ani dusus" || trend === "dusuyor") return "Not Dususu";
  if (absence !== null && (absence >= 0.2 || absence >= 20)) return "Devamsizlik Riski";
  if ((missingAssignments || 0) >= 2 || (lateAssignments || 0) >= 2) return "Odev Teslim Riski";
  if (risk === "kritik") return "Kritik Akademik Risk";
  return "Genel Akademik Risk";
}

function decideImportance(summary, prediction) {
  const riskLevel = normalize(summary?.fields?.Risk_Seviyesi || prediction?.fields?.Risk_Seviyesi);
  const riskScore = getNumber(summary?.fields?.Risk_Puani);

  if (riskLevel === "kritik" || (riskScore !== null && riskScore >= 85)) return "Kritik";
  if (riskLevel === "yuksek" || riskLevel === "yüksek" || (riskScore !== null && riskScore >= 70)) return "Yuksek";
  if (riskScore !== null && riskScore >= 50) return "Orta";

  return "Orta";
}

const summaries = getRecords("GET Student Summaries");
const predictions = getRecords("GET Predictions");
const existingSignals = getRecords("GET Existing Risk Signals");
const users = getRecords("GET Users");
const classes = getRecords("GET Classes");

const weekKey = getWeekKey();

const existingText = existingSignals
  .map((signal) => getString(signal.fields.Aciklama))
  .join("\n");

const candidates = [];

for (const summary of summaries) {
  const studentId = asLinks(summary.fields.Ogrenci)[0];
  const classId = asLinks(summary.fields.Sinif)[0];

  if (!studentId || !classId) continue;

  const matchingPrediction = predictions.find((prediction) => {
    return (
      asLinks(prediction.fields.Ogrenci).includes(studentId) &&
      asLinks(prediction.fields.Sinif).includes(classId)
    );
  });

  const trackingCode = `RISK_SIGNAL:${weekKey}:OZET:${summary.id}`;

  if (existingText.includes(trackingCode)) {
    continue;
  }

  const student = findUser(users, studentId);
  const classRecord = findClass(classes, classId);

  const teacherId = asLinks(classRecord?.fields?.Ogretmen)[0];
  const teacher = findUser(users, teacherId);

  if (!teacherId || !teacher?.fields?.Eposta) continue;

  const studentName =
    getString(student?.fields?.Ad_Soyad) ||
    getString(student?.fields?.Eposta) ||
    "Öğrenci";

  const className =
    getString(classRecord?.fields?.Sinif_Adi) ||
    getString(classRecord?.fields?.Ders_Adi) ||
    "Sınıf";

  const signalType = decideSignalType(summary, matchingPrediction);
  const importance = decideImportance(summary, matchingPrediction);

  const dataSummary = [
    `Öğrenci: ${studentName}`,
    `Sınıf: ${className}`,
    `Risk seviyesi: ${getString(summary.fields.Risk_Seviyesi) || getString(matchingPrediction?.fields?.Risk_Seviyesi) || "Yok"}`,
    `Risk puanı: ${getString(summary.fields.Risk_Puani) || "Yok"}`,
    `Genel ortalama: ${getString(summary.fields.Genel_Ortalama) || "Yok"}`,
    `Son 3 not ortalaması: ${getString(summary.fields.Son_3_Not_Ortalamasi) || "Yok"}`,
    `Not trendi: ${getString(summary.fields.Not_Trendi) || "Yok"}`,
    `Not düşüşü puanı: ${getString(summary.fields.Not_Dususu_Puani) || "Yok"}`,
    `Devamsızlık oranı: ${percentToText(summary.fields.Devamsizlik_Orani)}`,
    `Ödev teslim oranı: ${percentToText(summary.fields.Odev_Teslim_Orani)}`,
    `Geç teslim sayısı: ${getString(summary.fields.Gec_Teslim_Sayisi) || "0"}`,
    `Eksik ödev sayısı: ${getString(summary.fields.Eksik_Odev_Sayisi) || "0"}`,
    `Sınıf ortalamasına göre fark: ${getString(summary.fields.Sinif_Ortalamasina_Gore_Fark) || "Yok"}`,
    `AI önerisi: ${getString(summary.fields.AI_Onerisi) || "Yok"}`,
    matchingPrediction
      ? `AI tahmin özeti: ${getString(matchingPrediction.fields.Ozet) || getString(matchingPrediction.fields.Ogretmene_Gosterilecek) || "Yok"}`
      : "AI tahmin özeti: Yok",
    `Sinyal türü: ${signalType}`,
    `Önem derecesi: ${importance}`,
    `Takip kodu: ${trackingCode}`,
  ].join("\n");

  const aiPrompt = `
Sen AkıllıSınıf AI erken uyarı sistemi için çalışan Türkçe akademik risk analizi asistanısın.

Aşağıdaki öğrenci verisine göre öğretmenin anlayacağı kısa bir risk sinyali açıklaması ve uygulanabilir aksiyon önerisi üret.

Veri:
${dataSummary}

Çıktı formatı kesinlikle şu şekilde olsun:

ACIKLAMA:
2-4 cümlelik kısa açıklama.

ONERILEN_AKSIYON:
2-4 maddelik uygulanabilir öğretmen aksiyonu.

Kurallar:
- Türkçe yaz.
- Öğrenciyi suçlayıcı dil kullanma.
- Öğretmene karar desteği ver.
- Veride olmayan şeyi uydurma.
- Çok uzun yazma.
`;

  candidates.push({
    json: {
      trackingCode,
      studentId,
      studentName,
      classId,
      className,
      teacherId,
      teacherName: getString(teacher.fields.Ad_Soyad) || "Öğretmen",
      teacherEmail: getString(teacher.fields.Eposta),
      summaryId: summary.id,
      predictionId: matchingPrediction?.id || "",
      signalType,
      importance,
      riskScore: getNumber(summary.fields.Risk_Puani) || 70,
      dataSummary,
      aiPrompt,
    },
  });
}

return candidates;

