function getString(value) {
  return String(value || "").trim();
}

function tryParseJson(value) {
  if (typeof value !== "string") return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

function findTextDeep(value, depth = 0) {
  if (depth > 8 || value === null || value === undefined) return "";

  const parsed = tryParseJson(value);

  if (typeof parsed === "string") {
    return parsed.trim();
  }

  if (Array.isArray(parsed)) {
    for (const item of parsed) {
      const found = findTextDeep(item, depth + 1);
      if (found) return found;
    }
    return "";
  }

  if (typeof parsed === "object") {
    const directCandidates = [
      parsed?.choices?.[0]?.message?.content,
      parsed?.body?.choices?.[0]?.message?.content,
      parsed?.data?.choices?.[0]?.message?.content,
      parsed?.response?.choices?.[0]?.message?.content,
      parsed?.message?.content,
      parsed?.content,
      parsed?.text,
      parsed?.answer,
      parsed?.output,
      parsed?.body,
      parsed?.data,
      parsed?.response,
    ];

    for (const candidate of directCandidates) {
      const found = findTextDeep(candidate, depth + 1);
      if (found) return found;
    }

    for (const key of Object.keys(parsed)) {
      const found = findTextDeep(parsed[key], depth + 1);
      if (found) return found;
    }
  }

  return "";
}

function parseAiText(text, source) {
  const clean = getString(text);

  const aciklamaMatch = clean.match(/ACIKLAMA:\s*([\s\S]*?)(ONERILEN_AKSIYON:|$)/i);
  const aksiyonMatch = clean.match(/ONERILEN_AKSIYON:\s*([\s\S]*)/i);

  const fallbackDescription = [
    `${source.studentName} için ${source.signalType} kapsamında erken uyarı sinyali oluştu.`,
    `Risk puanı ${source.riskScore}, önem derecesi ${source.importance}.`,
    "Öğrencinin son akademik verileri öğretmen tarafından incelenmelidir.",
  ].join(" ");

  const fallbackAction = [
    "- Öğrenciyle kısa bir bireysel görüşme yapılmalı.",
    "- Eksik ödevler ve son not değişimleri kontrol edilmeli.",
    "- Gerekirse küçük hedefli bir destek planı oluşturulmalı.",
  ].join("\n");

  return {
    description: getString(aciklamaMatch?.[1]) || fallbackDescription,
    action: getString(aksiyonMatch?.[1]) || fallbackAction,
  };
}

function buildEmailHtml({ teacherName, studentName, className, signalType, importance, description, action, trackingCode }) {
