</div>
`;
}

const sourceItems = $items("Prepare Risk Signal Candidates");
const aiItems = $items("OpenRouter Risk Signal Text");

const today = new Date().toISOString().slice(0, 10);
const output = [];

for (let index = 0; index < sourceItems.length; index += 1) {
  const source = sourceItems[index]?.json || {};
  const ai = aiItems[index]?.json || {};

  const aiText = findTextDeep(ai);
  const parsed = parseAiText(aiText, source);

  const description = [
    parsed.description,
    "",
    `Takip kodu: ${source.trackingCode}`,
  ].join("\n");

  const action = parsed.action;

  output.push({
    json: {
      fields: {
        Sinyal_Adi: `${source.className} - ${source.studentName} - ${source.signalType}`,
        Ogrenci: [source.studentId],
        Sinif: [source.classId],
        Ozet: [source.summaryId],
        Sinyal_Turu: source.signalType,
        Risk_Puani: source.riskScore,
        Onem_Derecesi: source.importance,
        Aciklama: description,
        Onerilen_Aksiyon: action,
        Durum: "Yeni",
        Tespit_Tarihi: today,
      },
      notificationFields: {
        Bildirim_Basligi: "Yeni erken uyarı risk sinyali",
        Alici: [source.teacherId],
        Sinif: [source.classId],
        Bildirim_Turu: "Risk Sinyali",
        Mesaj: `${source.studentName} için ${source.signalType} sinyali oluşturuldu. Önem: ${source.importance}.`,
        Onem_Derecesi: source.importance === "Kritik" ? "Yüksek" : source.importance === "Yuksek" ? "Yüksek" : "Orta",
        Okundu_Mu: false,
        Gonderildi_Mi: true,
        Kanal: "E-posta + Webhook",
      },
      emailTo: source.teacherEmail,
      emailSubject: `Yeni risk sinyali: ${source.studentName}`,
      emailHtml: buildEmailHtml({
        teacherName: source.teacherName,
        studentName: source.studentName,
        className: source.className,
        signalType: source.signalType,
        importance: source.importance,
        description: parsed.description,
        action,
        trackingCode: source.trackingCode,
      }),
    },
  });
}

return output;
